    def test_names(self):
        self.assertEqual(name('general'), 'general')
        with self.assertRaises(Invalid):
            name('../general')

    def test_bools_are_not_counts(self):
        with self.assertRaises(Invalid):
            integer(True)

    def test_input_copy(self):
        source = {'items': ['guide']}
        result = object_value(source)
        source['items'].append('status')
        self.assertEqual(result, {'items': ['guide']})

from dataclasses import dataclass, asdict, replace
import hashlib
import json
from copy import deepcopy
from .errors import Missing, Refused, Conflict, Invalid
from .validation import name, text, integer

@dataclass(frozen=True)
class Plan:
    id: str
    tenant: str
    subject: str
    project: str
    document: str
    destination: str
    projection: str
    revision: int = 1

    def snapshot(self):
        return asdict(self)

    def digest(self):
        return hashlib.sha256(json.dumps(self.snapshot(), sort_keys=True).encode()).hexdigest()

class Plans:
    def __init__(self):
        self.rows = {}
        self.sequence = 0

    def create(self, principal, arguments):
        self.sequence += 1
        pid = 'plan-' + str(self.sequence)
        plan = Plan(pid, principal.tenant, principal.subject, name(arguments['project']),
                    name(arguments['document']), name(arguments['destination']),
                    self.projection(arguments.get('projection', 'title')))
        self.rows[pid] = plan
        return plan.snapshot()

    def projection(self, value):
        if value not in ('title', 'full'):
            raise Invalid('projection')
        return value

    def owned(self, principal, pid):
        plan = self.rows.get(pid)
        if plan is None:
            raise Missing('plan')
        if (plan.tenant, plan.subject) != (principal.tenant, principal.subject):
            raise Refused('plan owner')
        return plan

    def reviewable(self, principal, pid):
        plan = self.rows.get(pid)
        if plan is None:
            raise Missing('plan')
        if plan.tenant != principal.tenant:
            raise Refused('plan tenant')
        return plan

    def update(self, principal, arguments):
        plan = self.owned(principal, name(arguments['plan']))
        if plan.revision != integer(arguments['revision'], 1):
            raise Conflict('revision')
        updated = replace(plan, destination=name(arguments.get('destination', plan.destination)),
                          projection=self.projection(arguments.get('projection', plan.projection)),
                          revision=plan.revision + 1)
        self.rows[plan.id] = updated
        return updated.snapshot()

from dataclasses import dataclass
from copy import deepcopy
from .errors import Refused, Conflict

@dataclass
class Decision:
    tenant: str
    subject: str
    plan: str
    digest: str
    snapshot: dict
    reviewer: str
    consumed: bool = False

class Reviews:
    def __init__(self):
        self.decisions = {}

    def record(self, reviewer, plan):
        self.decisions[(plan.tenant, plan.id)] = Decision(plan.tenant, plan.subject,
            plan.id, plan.digest(), plan.snapshot(), reviewer.subject)
        return {'plan': plan.id, 'revision': plan.revision, 'reviewer': reviewer.subject}

    def consume(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        if decision is None or decision.subject != principal.subject:
            raise Refused('review')
        if decision.consumed:
            raise Conflict('review consumed')
        decision.consumed = True
        return deepcopy(decision.snapshot)

    def status(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        return {'reviewed': decision is not None, 'consumed': decision.consumed if decision else False}

import re
from .errors import Invalid

NAME = re.compile(r'[a-z][a-z0-9_-]{0,47}\Z')

def name(value):
    if not isinstance(value, str) or not NAME.fullmatch(value):
        raise Invalid('name')
    return value

def text(value, maximum=4096):
    if not isinstance(value, str) or len(value.encode('utf-8')) > maximum:
        raise Invalid('text')
    return value

def integer(value, low=0, high=1000000):
    if type(value) is not int or not low <= value <= high:
        raise Invalid('integer')
    return value

def object_value(value, depth=0):
    if depth > 8:
        raise Invalid('nesting')
    if value is None or type(value) in (bool, int):
        return value
    if isinstance(value, str):
        return text(value, 16384)
    if isinstance(value, list) and len(value) <= 64:
        return [object_value(v, depth + 1) for v in value]
    if isinstance(value, dict) and len(value) <= 64:
        if any(not isinstance(k, str) or len(k) > 64 for k in value):
            raise Invalid('object key')
        return {k: object_value(v, depth + 1) for k, v in value.items()}
    raise Invalid('object')

from collections import OrderedDict
from dataclasses import dataclass
from secrets import token_urlsafe
from .errors import Refused, Conflict

@dataclass(frozen=True)
class Session:
    id: str
    token: str
    subject: str
    tenant: str
    credential_id: str
    expires: float

class Sessions:
    def __init__(self, credentials, settings, clock):
        self.credentials = credentials
        self.settings = settings
        self.clock = clock
        self.rows = OrderedDict()

    def prune(self):
        now = self.clock.now()
        for sid, session in list(self.rows.items()):
            if session.expires <= now:
                del self.rows[sid]

    def open(self, token):
        principal = self.credentials.authenticate(token)
        self.prune()
        if len(self.rows) >= self.settings.session_capacity:
            raise Conflict('session capacity')
        sid = token_urlsafe(24)
        session = Session(sid, token, principal.subject, principal.tenant,
                          principal.credential_id, self.clock.now() + self.settings.session_ttl)
        self.rows[sid] = session
        return {'session': sid, 'expires_in': self.settings.session_ttl}

    def resolve(self, sid):
        self.prune()
        if not isinstance(sid, str):
            raise Refused('session')
        session = self.rows.get(sid)
        if session is None:
            raise Refused('session')
        principal = self.credentials.authenticate(session.token)
        if (principal.subject, principal.tenant, principal.credential_id) != (
                session.subject, session.tenant, session.credential_id):
            raise Refused('session identity')
        return session, principal

    def close(self, sid):
        session, _ = self.resolve(sid)
        del self.rows[session.id]
        return {'closed': True}

    def count(self):
        self.prune()
        return len(self.rows)
